import os
from google.cloud import documentai_v1 as documentai
from google.cloud import translate_v3 as translate
from google.cloud import aiplatform


def get_documentai_client(location: str):
    return documentai.DocumentProcessorServiceClient(
        client_options={"api_endpoint": f"{location}-documentai.googleapis.com"})


def get_translate_client():
    return translate.TranslationServiceClient()


def get_vertex_ai_model_garden_client(project_id: str, location: str):
    # Initialize Vertex AI for the given project and location
    aiplatform.init(project=project_id, location=location)
    return aiplatform

from google.cloud import documentai_v1 as documentai
from document_client import get_documentai_client
from document_models import DocumentPayload, DocumentConfig, LayoutExtractionResult


def extract_layout(payload: DocumentPayload, config: DocumentConfig) -> LayoutExtractionResult:
    client = get_documentai_client(config.location)
    name = client.processor_path(config.project_id, config.location, config.processor_id)

    raw_document = documentai.RawDocument(
        content=payload.document_bytes, mime_type=payload.mime_type
    )

    request = documentai.ProcessRequest(name=name, raw_document=raw_document)
    response = client.process_document(request=request)

    document = response.document

    pages_data = []
    for page in document.pages:
        page_text = "".join([text_element.text_segment.text for text_element in page.tokens])
        pages_data.append({
            "page_number": page.page_number,
            "dimension": {"width": page.dimension.width, "height": page.dimension.height},
            "text": page_text,
            "blocks": [{
                "bbox": [v.x, v.y for v in block.layout.bounding_poly.vertices],
                "text_segments": [{
                    "start_index": ts.start_index, "end_index": ts.end_index
                } for ts in block.layout.text_anchor.text_segments]
            } for block in page.blocks],
            "lines": [{
                "bbox": [v.x, v.y for v in line.layout.bounding_poly.vertices],
                "text_segments": [{
                    "start_index": ts.start_index, "end_index": ts.end_index
                } for ts in line.layout.text_anchor.text_segments]
            } for line in page.lines],
        })

    entities_data = []
    for entity in document.entities:
        entities_data.append({
            "type": entity.type,
            "mention_text": entity.mention_text,
            "confidence": entity.confidence,
            "bounding_poly": [v.x, v.y for v in entity.bounding_poly.vertices] if entity.bounding_poly else []
        })

    return LayoutExtractionResult(
        text=document.text,
        pages=pages_data,
        entities=entities_data
    )

from google.cloud import documentai_v1 as documentai
from document_client import get_documentai_client
from document_models import DocumentPayload, DocumentConfig, TableExtractionResult


def extract_tables(payload: DocumentPayload, config: DocumentConfig) -> TableExtractionResult:
    client = get_documentai_client(config.location)
    name = client.processor_path(config.project_id, config.location, config.processor_id)

    raw_document = documentai.RawDocument(
        content=payload.document_bytes, mime_type=payload.mime_type
    )

    request = documentai.ProcessRequest(name=name, raw_document=raw_document)
    response = client.process_document(request=request)

    document = response.document

    tables_data = []
    for page in document.pages:
        for table in page.tables:
            header_rows = []
            for row in table.header_rows:
                cells = []
                for cell in row.cells:
                    cells.append({
                        "text": client.common.text_anchor_to_string(cell.layout.text_anchor, document.text),
                        "row_span": cell.row_span,
                        "col_span": cell.col_span,
                    })
                header_rows.append({"cells": cells})

            body_rows = []
            for row in table.body_rows:
                cells = []
                for cell in row.cells:
                    cells.append({
                        "text": client.common.text_anchor_to_string(cell.layout.text_anchor, document.text),
                        "row_span": cell.row_span,
                        "col_span": cell.col_span,
                    })
                body_rows.append({"cells": cells})

            tables_data.append({
                "page_number": page.page_number,
                "header_rows": header_rows,
                "body_rows": body_rows,
                "text": client.common.text_anchor_to_string(table.layout.text_anchor, document.text)
            })

    return TableExtractionResult(tables=tables_data)

from google.cloud import translate_v3 as translate
from document_client import get_translate_client
from document_models import DocumentConfig, TranslationResult


def ocr_translate(text: str, target_language: str, config: DocumentConfig) -> TranslationResult:
    client = get_translate_client()
    parent = f"projects/{config.project_id}/locations/{config.location}"

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [text],
            "target_language_code": target_language,
        }
    )

    translations = response.translations
    if translations:
        first_translation = translations[0]
        return TranslationResult(
            translated_text=first_translation.translated_text,
            detected_language_code=first_translation.detected_language_code,
        )
    else:
        return TranslationResult(translated_text="")

from google.cloud import aiplatform
from document_client import get_vertex_ai_model_garden_client
from document_models import DocumentConfig, EmbeddingResult


def ocr_embedding(texts: list[str], config: DocumentConfig) -> EmbeddingResult:
    # Initialize Vertex AI
    aiplatform_client = get_vertex_ai_model_garden_client(config.project_id, config.location)

    # For text embeddings, we use a pre-trained text embedding model from Vertex AI.
    # The 'text-embedding-gecko@001' is a common choice.

    try:
        # Ensure the model is available and deployed
        # You can specify a different model_id in config if needed.
        model_id = config.model_id if config.model_id else "text-embedding-gecko@001"
        model = aiplatform.get_model(f"publishers/google/models/{model_id}")

        # Prepare instances for prediction
        instances = [{'content': text} for text in texts]

        # Make a prediction request
        response = model.predict(instances=instances)

        embeddings_list = []
        if response.predictions:
            for prediction in response.predictions:
                # Assuming the prediction directly contains the embedding vector
                # The structure might vary based on the specific embedding model
                if 'embeddings' in prediction and 'values' in prediction['embeddings']:
                    embeddings_list.append(prediction['embeddings']['values'])
                else:
                    print(f"Warning: Unexpected prediction format: {prediction}")

        return EmbeddingResult(embeddings=embeddings_list)
    except Exception as e:
        print(f"Error during embedding generation: {e}")
        return EmbeddingResult(embeddings=[])
